Read labels from `problem!A1:A10` and split each corresponding `B` cell on whitespace to extract its numbers. Build one result row per number, and one row with an empty `B` for labels that have no numbers. Write the resulting 28 rows as plain values into `result!A1:B28`.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

if "result" not in wb.sheetnames:
    ws = wb.create_sheet("result")
else:
    ws = wb["result"]

p = vals["problem"]
rows = []

for r in range(1, 11):
    label_val = p.cell(row=r, column=1).value
    label = str(label_val).strip() if label_val is not None else ""

    b_val = p.cell(row=r, column=2).value
    nums = []

    if b_val is not None:
        if isinstance(b_val, (int, float)) and not isinstance(b_val, bool):
            nums.append(b_val)
        else:
            for token in str(b_val).split():
                t = token.strip().replace(",", "")
                if not t:
                    continue
                try:
                    if any(ch in t for ch in ".eE"):
                        nums.append(float(t))
                    else:
                        nums.append(int(t))
                except ValueError:
                    pass

    if nums:
        for n in nums:
            rows.append((label, n))
    else:
        rows.append((label, None))

for r in range(1, 29):
    if r <= len(rows):
        label, num = rows[r - 1]
        ws.cell(row=r, column=1, value=label if label else None)
        ws.cell(row=r, column=2, value=num)
    else:
        ws.cell(row=r, column=1, value=None)
        ws.cell(row=r, column=2, value=None)

wb.save(OUT)

print("rows:", len(rows))
print("first:", rows[:3])
print("last:", rows[-3:])
